import os
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import Optional

app = FastAPI()

# Directory to store queue data
DATA_DIR = "/workdir/data"
os.makedirs(DATA_DIR, exist_ok=True)

# Data structure: queue_name -> list of messages (FIFO order)
queues = {}

class QueueCreateRequest(BaseModel):
    name: str

class MessageRequest(BaseModel):
    content: str

@app.post("/queues")
def create_queue(request: QueueCreateRequest):
    queue_name = request.name
    # Check if queue already exists
    if queue_name in queues:
        raise HTTPException(status_code=400, detail="Queue already exists")
    queues[queue_name] = []
    return {"name": queue_name}

@app.post("/queues/{name}/messages")
def send_message(name: str, request: MessageRequest):
    if name not in queues:
        raise HTTPException(status_code=404, detail="Queue not found")
    queues[name].append(request.content)
    return {"content": request.content}

@app.get("/queues/{name}/messages")
def receive_message(name: str):
    if name not in queues:
        raise HTTPException(status_code=404, detail="Queue not found")
    if len(queues[name]) == 0:
        raise HTTPException(status_code=204, detail="No content")
    # Remove and return the first message (FIFO)
    message = queues[name].pop(0)
    return {"content": message}

@app.get("/status")
def get_status():
    return {"status": "ok", "queues": list(queues.keys())}

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
